/* HRM › Recruitment › Career page: admin (C1, C2) and the public, candidate-facing site (C3–C5). */
(function () {
  const { S, esc, acts, ins, chs } = App; const H = App.H;
  const live = () => S.recruitments.filter(r => r.published && r.status !== 'Draft' && r.status !== 'Closed');
  const url = () => `careers.leafease.com/${S.career.slug}`;
  const cq = App.ui.careerQ = { q: '' };
  const ST = { Open: 't-green', 'Closing soon': 't-orange' };

  /* ---------- admin ---------- */
  H.route('/hrm/careers', () => { const on = S.career.live; const l = live().filter(r => !cq.q || r.title.toLowerCase().includes(cq.q.toLowerCase()));
    return H.frame({ tab: 'careers', primary: `<button class="btn primary lg" data-act="rec-new"><i class="ri-add-circle-line"></i>New recruitment</button>`, title: 'Career page', sub: 'What candidates see when they visit your public jobs page.',
      actions: `<button class="btn outlined lg" data-go="#/careers"><i class="ri-eye-line"></i>Preview page</button>`,
      body: `<div class="hbody stack g24"><section class="live-card ${on ? '' : 'off'}"><span class="fic big ${on ? '' : 'warn'}"><i class="${on ? 'ri-global-line' : 'ri-error-warning-line'}"></i></span>
        <div class="grow stack g8"><div class="row g8"><b style="font-size:16px;font-weight:500">Public career page is ${on ? 'live' : 'off'}</b>${on ? '<span class="chip sm filled t-green"><span class="dot t-green"></span>Live</span>' : App.chip('Hidden', 't-orange', 'sm filled')}</div><span class="body2 muted">${on ? 'Anyone with the link can browse open roles and apply — no account needed.' : 'Turn it on so candidates can browse open roles and apply without an account.'}</span>
          <div class="url-box ${on ? '' : 'dim'}"><a href="#/careers" class="link">${url()}</a><button class="icon-btn s20 sq" data-act="cp-copy" aria-label="Copy link"><i class="ri-file-copy-line"></i></button><button class="icon-btn s20 sq" data-go="#/careers" aria-label="Open public page"><i class="ri-external-link-line"></i></button><button class="icon-btn s20 sq" data-act="cp-slug" aria-label="Edit link"><i class="ri-pencil-line"></i></button></div></div>
        ${on ? `<div class="cp-stat"><small>Page views</small><b>${App.fmt(S.career.views)}</b><small>this month</small></div><div class="cp-stat"><small>Applications</small><b>${S.career.apps}</b><small>via career page</small></div>` : ''}
        <div class="stack g4" style="align-items:center">${App.sw(on, 'data-ch="cp-live"', 'Publish career page')}<span class="caption ${on ? 'brand' : ''}">${on ? 'Published' : 'Off'}</span></div></section>
      ${on && live().length ? `<div class="row between wrap g12"><div class="row g8"><b class="sub2" style="font-size:16px">Open positions</b>${App.chip(live().length + ' published', 't-teal', 'sm filled')}</div><div class="row g12"><div style="width:min(280px,100%)">${App.field('Search', `<span class="adorn"><i class="ri-search-line"></i></span><input data-in="cp-q" value="${esc(cq.q)}" placeholder="Search roles…">`, { cls: 'sm' })}</div><button class="btn outlined" data-act="soon" data-what="Role filters"><i class="ri-filter-3-line"></i>Filter</button></div></div>
        <div class="role-grid">${l.map(r => { const n = S.candidates.filter(c => c.rid === r.id).length; const ini = r.title.split(' ').map(w => w[0]).join('').slice(0, 2); return `<article class="card role-adm"><div class="row g12">${H.av(ini, 'lg sq')}<div class="grow cell2"><b style="font-size:16px;font-weight:500">${esc(r.title)}</b><small>${esc(r.type)} · ${esc(r.location)}</small></div>${App.chip(r.status, ST[r.status] || 't-grey', 'sm filled')}</div>
          <div class="facts3"><div><small>Candidates</small><b>${n}</b></div><div><small>Vacancies</small><b>${r.vacancies} opening${r.vacancies > 1 ? 's' : ''}</b></div><div><small>Deadline</small><b>${esc(r.deadline)}</b></div></div>
          <div class="stack g4"><div class="row between caption"><span>${r.hired} hired of ${r.vacancies} vacancies</span><span class="brand">Published</span></div>${H.prog(r.hired, r.vacancies)}</div>
          <div class="g2"><button class="btn outlined" data-act="rec-view" data-id="${r.id}">View details</button><button class="btn tonal" data-act="cp-add" data-id="${r.id}"><i class="ri-user-add-line"></i>Add candidate</button></div></article>`; }).join('') || '<p class="caption">No roles match.</p>'}</div>`
      : `<div class="empty-box"><div class="empty"><span class="ic"><i class="ri-briefcase-4-line"></i></span><h2 class="sub2" style="font-size:18px;font-weight:400">${on ? 'No open recruitments right now' : 'Your career page is hidden'}</h2><p>${on ? 'Published recruitments appear here automatically. Create one, or publish a draft from Recruitments.' : 'Published recruitments appear here once you turn the page on.'}</p><div class="row g12 wrap" style="justify-content:center"><button class="btn outlined lg" data-go="#/hrm/recruitments">Go to recruitments</button><button class="btn primary lg" data-act="rec-new"><i class="ri-add-circle-line"></i>Create recruitment</button></div></div></div>`}</div>` }); });
  chs['cp-live'] = el => { S.career.live = el.checked; App.render(); App.snack(el.checked ? 'Career page is live.' : 'Career page hidden — the link now shows “no open roles”.', el.checked ? 'success' : 'info'); };
  ins['cp-q'] = el => { cq.q = el.value; const p = el.selectionStart; App.render(); const i = App.$('[data-in=cp-q]'); i.focus(); i.setSelectionRange(p, p); };
  acts['cp-copy'] = () => { try { navigator.clipboard.writeText('https://' + url())?.catch?.(() => {}); } catch (e) {} App.snack('Career page link copied.', 'info'); };
  acts['cp-slug'] = () => App.dialog(`${App.dlgHead('Edit career page link', 'Changing it breaks links you’ve already shared.')}<div class="dlg-body">${App.field('Link', `<span class="caption">careers.leafease.com/</span><input data-in="cp-slug" value="${esc(S.career.slug)}">`)}</div><div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="cp-slug-go">Save</button></div>`, { width: 520 });
  let slug = null; ins['cp-slug'] = el => { slug = el.value.toLowerCase().replace(/[^a-z0-9-]/g, '-'); };
  acts['cp-slug-go'] = () => { if (slug) S.career.slug = slug; App.closeModal(); App.render(); App.snack('Link updated.'); };
  acts['cp-add'] = el => { App.ui.hrmNew = { rid: el.dataset.id, stage: 'applied' }; App.go('#/hrm/candidates/new'); };

  /* ---------- public site ---------- */
  const PUB = { key: '', icon: '', title: 'Careers', public: true };
  const pf = App.ui.pubf = { q: '', dept: [], type: [], loc: [], sort: 'Newest' };
  const head = () => `<header class="pub-head"><div class="pub-in row between"><a href="#/careers" class="row g12 plain"><span class="qr">QR</span><span class="cell2"><b style="font-weight:500;font-size:16px">QA Riverside Private Clinic</b><small>Careers</small></span></a><nav class="row g16 wrap"><a href="#" data-act="soon" data-what="Clinic website" class="plain">Our clinic</a><a href="#" data-act="soon" data-what="Clinic website" class="plain">Benefits</a><a href="#" data-act="soon" data-what="Clinic website" class="plain">Contact</a><button class="btn outlined sm" data-act="soon" data-what="Clinic website">Visit website <i class="ri-external-link-line"></i></button><a href="#/hrm/careers" class="exit-prev"><i class="ri-arrow-go-back-line"></i>Exit preview</a></nav></div></header>`;
  const foot = '<p class="powered">Powered by <b>Aqlios</b></p>';
  const facet = (title, key, vals) => `<span class="overline strong">${title}</span>${vals.map(([v, n]) => `<label class="cbx facet"><input type="checkbox" data-ch="pub-f" data-k="${key}" value="${esc(v)}" ${pf[key].includes(v) ? 'checked' : ''}>${esc(v)}<span class="caption">${n}</span></label>`).join('')}`;
  App.route('/careers', () => { const all = S.career.live ? live() : [];
    const l = all.filter(r => (!pf.q || (r.title + ' ' + r.blurb).toLowerCase().includes(pf.q.toLowerCase())) && (!pf.dept.length || pf.dept.includes(r.dept)) && (!pf.type.length || pf.type.includes(r.type)) && (!pf.loc.length || pf.loc.includes(r.location)));
    if (pf.sort === 'Closing soon') l.sort((a, b) => a.closesIn - b.closesIn);
    const cnt = k => [...new Set(all.map(r => r[k]))].map(v => [v, all.filter(r => r[k] === v).length]);
    const filtered = pf.q || pf.dept.length || pf.type.length || pf.loc.length;
    return `<div class="pub">${head()}<section class="pub-hero"><div class="pub-in stack g16"><span class="overline brand strong">Join our team</span><h1 class="pub-h1">Build a career in patient-first care</h1><p class="body1 muted" style="margin:0">We are a growing private clinic in South London. Explore open roles and apply in minutes — no account needed.</p>
      <form class="pub-search" data-act="noop" onsubmit="return false"><i class="ri-search-line"></i><input data-in="pub-q" value="${esc(pf.q)}" placeholder="Job title or keyword" aria-label="Job title or keyword"><button class="btn primary" type="button" data-act="pub-search">Search roles</button></form></div></section>
      <div class="pub-in pub-grid"><aside class="card card-pad stack g8 facets"><b style="font-weight:500;font-size:15px">Filter roles</b>${facet('Department', 'dept', cnt('dept'))}${facet('Employment type', 'type', cnt('type'))}${facet('Location', 'loc', cnt('location'))}${filtered ? '<button class="linkish" data-act="pub-clear" style="align-self:flex-start">Clear filters</button>' : ''}</aside>
      <div class="stack g16"><div class="row between"><span class="body1">${l.length} of ${all.length} roles${filtered ? ' · filtered' : ''}</span><label class="caption row g4">Sort: <select class="inline-sel" data-ch="pub-sort">${['Newest', 'Closing soon'].map(s => `<option ${s === pf.sort ? 'selected' : ''}>${s}</option>`).join('')}</select></label></div>
        ${l.map(r => `<article class="card role-pub"><span class="av lg sq">${r.title.split(' ').map(w => w[0]).join('').slice(0, 2)}</span><div class="grow stack g8"><div class="row g8 wrap"><a href="#/careers/${r.id}" class="plain"><b style="font-size:18px;font-weight:500">${esc(r.title)}</b></a>${r.isNew ? App.chip('New', 't-green', 'sm filled') : ''}</div><div class="row g8 wrap">${[r.type, r.location, `${r.vacancies} opening${r.vacancies > 1 ? 's' : ''}`].map(t => App.chip(t, 't-grey', 'sm filled')).join('')}</div><p class="body2 muted" style="margin:0">${esc(r.blurb)}</p></div>
          <div class="stack g12" style="align-items:flex-end"><span class="caption"><i class="ri-time-line"></i> Closes in ${r.closesIn} days</span><div class="row g8"><button class="btn outlined" data-go="#/careers/${r.id}">View role</button><button class="btn primary" data-act="pub-apply" data-id="${r.id}">Apply now <i class="ri-arrow-right-s-line"></i></button></div></div></article>`).join('') || `<div class="card empty"><span class="ic"><i class="ri-briefcase-4-line"></i></span><h2 class="sub2" style="font-size:18px;font-weight:400">${all.length ? 'No roles match your search' : 'No open roles right now'}</h2><p>${all.length ? 'Try a different keyword or clear the filters.' : 'Check back soon — new roles appear here as soon as they open.'}</p>${all.length ? '<button class="btn outlined" data-act="pub-clear">Clear filters</button>' : ''}</div>`}${foot}</div></div></div>`; }, PUB);
  ins['pub-q'] = el => { pf.q = el.value; }; acts['pub-search'] = () => App.render();
  document.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.matches?.('[data-in=pub-q]')) { e.preventDefault(); App.render(); } });
  chs['pub-f'] = el => { const k = el.dataset.k; pf[k] = el.checked ? [...pf[k], el.value] : pf[k].filter(v => v !== el.value); App.render(); };
  chs['pub-sort'] = el => { pf.sort = el.value; App.render(); };
  acts['pub-clear'] = () => { Object.assign(pf, { q: '', dept: [], type: [], loc: [] }); App.render(); };
  acts['pub-apply'] = el => { App.ui.scrollApply = true; App.go('#/careers/' + el.dataset.id); };

  /* role detail + apply (C4) */
  let ap = null;
  App.route('/careers/:id', id => { const r = H.rec(id); if (!r || !live().includes(r) || !S.career.live) return `<div class="pub">${head()}<div class="pub-in" style="padding:48px 0"><div class="card empty"><span class="ic"><i class="ri-briefcase-4-line"></i></span><h2 class="sub2" style="font-size:18px;font-weight:400">This role is no longer open</h2><p>It may have been filled or closed.</p><button class="btn outlined" data-go="#/careers">See open roles</button></div></div></div>`;
    if (!ap || ap.rid !== id) ap = { rid: id, first: '', last: '', email: '', phone: '', gender: '', linkedin: '', cv: null, answers: {}, consent: false, tried: false };
    const sv = S.surveys.find(s => s.id === r.survey); const e = k => ap.tried && !String(ap[k]).trim();
    if (App.ui.scrollApply) { App.ui.scrollApply = false; App.after(() => App.$('#apply')?.scrollIntoView({ behavior: 'smooth' })); }
    return `<div class="pub">${head()}<div class="pub-in stack g16" style="padding:24px 0 48px"><a href="#/careers" class="plain row g8 body2"><i class="ri-arrow-left-line"></i>Back to open roles</a>
      <div class="role-detail"><article class="card card-pad stack g16"><div class="row g8 caption"><span class="qr sm">QR</span>QA Riverside Private Clinic · ${esc(r.location)}</div><div class="row between g12"><h1 class="pub-h2">${esc(r.title)}</h1><button class="btn outlined" data-act="pub-share"><i class="ri-share-line"></i>Share</button></div>
        <div class="row g16 wrap caption meta" style="color:var(--text)"><span><i class="ri-briefcase-line"></i>${esc(r.type)}</span><span><i class="ri-team-line"></i>${r.vacancies} opening${r.vacancies > 1 ? 's' : ''}</span><span><i class="ri-calendar-line"></i>Opens ${esc(r.start)}</span><span><i class="ri-time-line"></i>Closes ${esc(r.end)}</span></div>
        <div class="row g8 wrap">${r.skills.map(s => App.chip(s, 't-teal', 'sm filled')).join('')}</div><hr class="hr">
        <h2 class="sub2" style="font-size:16px;font-weight:600">About the role</h2><p class="body2" style="margin:0">${esc(r.desc)}</p>
        <h2 class="sub2" style="font-size:16px;font-weight:600">Requirements</h2><ul class="checklist roomy">${r.reqs.map(q => `<li><i class="ri-check-line ok-bg"></i>${esc(q)}</li>`).join('')}</ul>
        <h2 class="sub2" style="font-size:16px;font-weight:600">What we offer</h2><p class="body2" style="margin:0">Competitive salary · 30 days annual leave · Indemnity cover · CPD budget · Flexible sessions · Modern clinic with integrated EHR</p></article>
      <form class="card card-pad stack g16 apply" id="apply" onsubmit="return false" novalidate><div><h2 class="h6" style="font-size:20px;font-weight:500">Apply for this role</h2><p class="caption" style="margin:0">Takes about 5 minutes. Fields marked * are required.</p></div>
        ${ap.tried && !valid(sv) ? '<div class="al" role="alert"><i class="ri-error-warning-line"></i><div class="txt">Please complete the highlighted fields.</div></div>' : ''}
        <div class="g2">${pubField('First name', 'first', true, e('first'))}${pubField('Last name', 'last', true, e('last'))}</div>
        ${pubField('Email', 'email', true, ap.tried && !okEmail(ap.email), 'email', ap.tried && ap.email && !okEmail(ap.email) ? 'Enter a valid email address, e.g. name@example.com' : '')}
        <div class="g2">${pubField('Phone', 'phone', false, false, 'tel')}<label class="pfield"><span>Gender</span><select data-ch="ap-gender"><option value="">Prefer not to say</option>${['Female', 'Male', 'Non-binary'].map(g => `<option ${ap.gender === g ? 'selected' : ''}>${g}</option>`).join('')}</select></label></div>
        ${pubField('LinkedIn or portfolio', 'linkedin', false)}
        <div class="stack g4"><span class="body2">Resume${r.resumeOptional ? '' : ' <b class="req">*</b>'}</span>${ap.cv ? `<div class="file-row tint"><span class="fic"><i class="ri-file-text-line"></i></span><div class="grow cell2"><span>${esc(ap.cv)}</span><small>480 KB · Uploaded</small></div><button class="icon-btn s20" type="button" data-act="ap-cv-x" aria-label="Remove file"><i class="ri-close-line"></i></button></div>` : `<label class="dropzone sm ${ap.tried && !r.resumeOptional ? 'err' : ''}"><input type="file" hidden accept=".pdf,.doc,.docx" data-ch="ap-cv"><i class="ri-upload-cloud-2-line"></i><span class="brand">Upload your CV</span><span class="caption">PDF or DOCX, up to 10 MB</span></label>`}</div>
        ${sv ? `<hr class="hr"><div class="row g8"><b style="font-weight:500;font-size:16px">${esc(sv.name)}</b><span class="chip sm">${sv.questions.length} questions</span></div>${sv.questions.map((q, i) => { const bad = ap.tried && q.required && !(ap.answers[i] || '').trim(); return `<label class="pfield ${bad ? 'err' : ''}"><span>${esc(q.q)}${q.required ? ' <b class="req">*</b>' : ''}</span>${q.type === 'Yes / No' ? `<select data-ch="ap-ans" data-i="${i}"><option value="">Choose…</option>${['Yes — full registration', 'No'].map(o => `<option ${ap.answers[i] === o ? 'selected' : ''}>${o}</option>`).join('')}</select>` : q.type === 'Multiple choice' ? `<select data-ch="ap-ans" data-i="${i}"><option value="">Choose…</option>${(q.options || []).map(o => `<option ${ap.answers[i] === o ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select>` : `<textarea rows="3" data-in="ap-ans" data-i="${i}" placeholder="Your answer">${esc(ap.answers[i] || '')}</textarea>`}</label>`; }).join('')}` : ''}
        <label class="cbx top ${ap.tried && !ap.consent ? 'err' : ''}"><input type="checkbox" data-ch="ap-consent" ${ap.consent ? 'checked' : ''}><span class="caption" style="color:var(--text)">I agree that QA Riverside Private Clinic may store my details for this and future roles.</span></label>
        <button class="btn primary lg full" type="button" data-act="ap-go">Submit application</button></form></div>${foot}</div></div>`; }, PUB);
  const okEmail = v => /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(v);
  const pubField = (label, k, req, bad, type = 'text', msg = '') => `<label class="pfield ${bad ? 'err' : ''}"><span>${label}${req ? ' <b class="req">*</b>' : ''}</span><input type="${type}" data-in="ap" data-k="${k}" value="${esc(ap[k])}" ${req ? 'aria-required="true"' : ''}>${msg ? `<small class="helper err" style="margin:0">${msg}</small>` : ''}</label>`;
  const valid = sv => ap.first.trim() && ap.last.trim() && okEmail(ap.email) && (ap.cv || H.rec(ap.rid).resumeOptional) && ap.consent && (!sv || sv.questions.every((q, i) => !q.required || (ap.answers[i] || '').trim()));
  ins.ap = el => { ap[el.dataset.k] = el.value; }; ins['ap-ans'] = el => { ap.answers[el.dataset.i] = el.value; }; chs['ap-ans'] = el => { ap.answers[el.dataset.i] = el.value; };
  chs['ap-gender'] = el => { ap.gender = el.value; }; chs['ap-consent'] = el => { ap.consent = el.checked; };
  chs['ap-cv'] = el => { const f = el.files[0]; if (f) { ap.cv = f.name; App.render(); } }; acts['ap-cv-x'] = () => { ap.cv = null; App.render(); };
  acts['pub-share'] = () => { try { navigator.clipboard.writeText(location.href)?.catch?.(() => {}); } catch (e) {} App.snack('Link copied — share it with a friend.', 'info'); };
  acts['ap-go'] = () => { const r = H.rec(ap.rid); const sv = S.surveys.find(s => s.id === r.survey);
    if (!valid(sv)) { ap.tried = true; App.render(); App.$('#apply')?.scrollIntoView({ behavior: 'smooth' }); return; }
    const c = { id: 'c' + Date.now(), first: ap.first.trim(), last: ap.last.trim(), rid: r.id, stage: 'applied', status: 'progress', rating: 0, source: 'Career page', when: 'Just now', applied: '08 Oct', location: 'London, UK', pools: [], active: true, email: ap.email.trim(), phone: ap.phone, linkedin: ap.linkedin, gender: ap.gender || '—', dob: '—', address: '—', country: 'United Kingdom', referral: '—', cv: ap.cv || null, isNew: true,
      log: [{ icon: 'ri-global-line', text: `Applied via the career page${sv ? ` · answered “${sv.name}”` : ''}`, at: '08 Oct, ' + new Date().toTimeString().slice(0, 5), by: ap.first.trim() }] };
    S.candidates.unshift(c); S.career.apps++; App.ui.sent = { first: c.first, email: c.email, title: r.title, cid: c.id }; ap = null; App.go('#/careers/' + r.id + '/sent'); };

  /* submitted (C5) */
  App.route('/careers/:id/sent', () => { const s = App.ui.sent || { first: 'there', email: 'your inbox', title: 'this role' };
    return `<div class="pub">${head()}<div class="pub-in" style="padding:56px 0"><section class="card sent-card"><span class="ok-circle"><i class="ri-check-line"></i></span><h1 class="pub-h2" style="font-size:24px">Application sent</h1><p class="body2 muted" style="margin:0;max-width:440px">Thanks, ${esc(s.first)}. Your application for ${esc(s.title)} has reached our hiring team. We’ve emailed a copy to <b style="color:var(--text)">${esc(s.email)}</b>.</p>
      <div class="next-box"><b>What happens next</b>${['We review applications within 5 working days', 'Shortlisted candidates are invited to interview', 'You’ll hear from us by email either way'].map((t, i) => `<div class="row g12"><span class="num-dot">${i + 1}</span>${t}</div>`).join('')}</div>
      <div class="row g12 wrap" style="justify-content:center"><button class="btn outlined lg" data-go="#/careers">Browse other roles</button><button class="btn primary lg" data-act="soon" data-what="Clinic website">Visit our website</button></div>
      ${s.cid ? `<div class="proto-note"><i class="ri-flask-line"></i>Prototype: <a href="#/hrm/candidates/${s.cid}" class="link">see ${esc(s.first)} land in Applied on the pipeline →</a></div>` : ''}</section>${foot}</div></div>`; }, PUB);
})();
